package com.collaboffice.user.service;
import com.alibaba.fastjson2.JSON;
import com.collaboffice.common.exception.BusinessException;
import com.collaboffice.common.security.WorkspaceAccess;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.time.LocalDateTime;

@Service @RequiredArgsConstructor
public class OrganizationService {
 private final JdbcTemplate jdbc;private final WorkspaceAccess access;
 public void admin(Long space){access.requireSystemAdmin();access.requireSpace(space,false);if(!access.isAdmin(space))throw new BusinessException(403,"仅团队管理员可操作");}
 public Map<String,Object> state(Long space){access.requireSpace(space,false);var result=new LinkedHashMap<String,Object>();result.put("departments",jdbc.queryForList("SELECT id,parent_id AS parentId,dept_name AS name,leader_id AS leaderId,dept_sort AS sort FROM sys_dept WHERE space_id=? AND deleted=0 ORDER BY dept_sort,id",space));result.put("roles",jdbc.queryForList("SELECT id,name,permissions_json AS permissions FROM workspace_role WHERE space_id=? ORDER BY id",space));result.put("members",jdbc.queryForList("SELECT m.user_id AS userId,m.dept_id AS deptId,m.custom_role_id AS customRoleId,m.expires_at AS expiresAt,m.role_type AS roleType,u.username,COALESCE(u.real_name,u.username) AS name,u.online_status AS onlineStatus,u.last_login_time AS lastActive FROM sys_space_member m JOIN sys_user u ON u.id=m.user_id WHERE m.space_id=? ORDER BY m.id",space));result.put("space",access.row("SELECT id,owner_id AS ownerId,space_name AS name,space_logo AS logo,description,storage_quota AS quota,security_config_json AS security FROM sys_space WHERE id=? AND deleted=0",space));if(access.isAdmin(space))result.put("audit",jdbc.queryForList("SELECT actor_id AS actorId,action,target,created_at AS createdAt FROM workspace_audit WHERE space_id=? ORDER BY id DESC LIMIT 100",space));return result;}
 public static void permissions(Map<String,Object> input){if(!input.keySet().equals(Set.of("view","edit","download","share","delete"))||input.values().stream().anyMatch(v->!(v instanceof Boolean))||!Boolean.TRUE.equals(input.get("view"))&&input.values().stream().anyMatch(Boolean.TRUE::equals))throw new BusinessException(400,"权限必须包含五个布尔操作，其他操作须同时允许查看");}
 private String name(Object v,int max){String n=Objects.toString(v,"").trim();if(n.isEmpty()||n.length()>max)throw new BusinessException(400,"名称长度无效");return n;}
 private Long id(Object v){return v==null||v.toString().isBlank()?null:Long.valueOf(v.toString());}
 @Transactional public void department(Long space,Map<String,Object> b){admin(space);Long key=id(b.get("id")),parent=id(b.get("parentId")),leader=id(b.get("leaderId"));if(key!=null)dept(space,key);if(parent!=null){dept(space,parent);var seen=new HashSet<Long>();Long current=parent;while(current!=null&&current!=0){if(Objects.equals(current,key)||!seen.add(current)||seen.size()>50)throw new BusinessException(400,"部门结构存在循环或超过50层");current=id(dept(space,current).get("parent_id"));}}if(leader!=null)member(space,leader);String title=name(b.get("name"),50);if(key==null)jdbc.update("INSERT INTO sys_dept(space_id,parent_id,dept_name,leader_id,dept_sort) VALUES(?,?,?,?,?)",space,parent,title,leader,0);else jdbc.update("UPDATE sys_dept SET parent_id=?,dept_name=?,leader_id=? WHERE id=?",parent,title,leader,key);audit(space,"department.save",Objects.toString(key,"new"),b);}
 private Map<String,Object> dept(Long space,Long id){var d=access.row("SELECT id,parent_id,space_id FROM sys_dept WHERE id=? AND deleted=0",id);if(!Objects.equals(((Number)d.get("space_id")).longValue(),space))throw new BusinessException(403,"部门不属于此团队");return d;}
 @Transactional public void deleteDepartment(Long space,Long id){admin(space);dept(space,id);if(jdbc.queryForObject("SELECT COUNT(*) FROM sys_dept WHERE parent_id=? AND deleted=0",Integer.class,id)>0||jdbc.queryForObject("SELECT COUNT(*) FROM sys_space_member WHERE dept_id=?",Integer.class,id)>0)throw new BusinessException(409,"请先移走子部门和成员");jdbc.update("UPDATE sys_dept SET deleted=1 WHERE id=?",id);audit(space,"department.delete",id.toString(),Map.of());}
 @Transactional public void role(Long space,Map<String,Object> b){admin(space);Long key=id(b.get("id"));if(!(b.get("permissions") instanceof Map<?,?>))throw new BusinessException(400,"权限格式无效");var perms=(Map<String,Object>)b.get("permissions");permissions(perms);String title=name(b.get("name"),50);if(key==null)jdbc.update("INSERT INTO workspace_role(space_id,name,permissions_json) VALUES(?,?,?)",space,title,JSON.toJSONString(perms));else{if(jdbc.queryForObject("SELECT COUNT(*) FROM workspace_role WHERE id=? AND space_id=?",Integer.class,key,space)==0)throw new BusinessException(404,"角色不存在");jdbc.update("UPDATE workspace_role SET name=?,permissions_json=? WHERE id=?",title,JSON.toJSONString(perms),key);}audit(space,"role.save",Objects.toString(key,"new"),b);}
 @Transactional public void deleteRole(Long space,Long id){admin(space);if(jdbc.queryForObject("SELECT COUNT(*) FROM sys_space_member WHERE custom_role_id=? AND space_id=?",Integer.class,id,space)>0)throw new BusinessException(409,"角色仍在使用");jdbc.update("DELETE FROM workspace_role WHERE id=? AND space_id=?",id,space);audit(space,"role.delete",id.toString(),Map.of());}
 private Map<String,Object> member(Long space,Long user){var rows=jdbc.queryForList("SELECT * FROM sys_space_member WHERE space_id=? AND user_id=?",space,user);if(rows.isEmpty())throw new BusinessException(404,"成员不存在");return rows.get(0);}
 @Transactional public void memberSettings(Long space,Long user,Map<String,Object> b){admin(space);member(space,user);Long role=id(b.get("customRoleId")),dept=id(b.get("deptId"));if(role!=null&&jdbc.queryForObject("SELECT COUNT(*) FROM workspace_role WHERE id=? AND space_id=?",Integer.class,role,space)==0)throw new BusinessException(400,"角色不存在");if(dept!=null)dept(space,dept);var owner=jdbc.queryForObject("SELECT owner_id FROM sys_space WHERE id=?",Long.class,space);if(owner.equals(user))throw new BusinessException(400,"创建者不设置临时或自定义权限");LocalDateTime expiry=b.get("expiresAt")==null||b.get("expiresAt").toString().isBlank()?null:LocalDateTime.parse(b.get("expiresAt").toString());jdbc.update("UPDATE sys_space_member SET custom_role_id=?,dept_id=?,expires_at=? WHERE space_id=? AND user_id=?",role,dept,expiry,space,user);audit(space,"member.permissions",user.toString(),b);}
 @Transactional public void transfer(Long space,Long target){
  // Use the same role lock as identity changes to keep the recipient eligible until commit.
  jdbc.queryForList("SELECT id FROM sys_role WHERE LOWER(role_code) IN ('admin','role_admin') FOR UPDATE");
  admin(space);
  var s=access.row("SELECT owner_id FROM sys_space WHERE id=? FOR UPDATE",space);
  if(!Objects.equals(((Number)s.get("owner_id")).longValue(),access.userId()))throw new BusinessException(403,"仅创建者可以转让");
  if(target==null||target.equals(access.userId()))throw new BusinessException(400,"请选择另一位系统管理员");
  member(space,target);
  if(!"SYSTEM_ADMIN".equals(access.platformRole(target)))throw new BusinessException(400,"接收成员必须是启用的系统管理员");
  jdbc.update("UPDATE sys_space SET owner_id=? WHERE id=?",target,space);
  jdbc.update("UPDATE sys_space_member SET role_type='1',custom_role_id=NULL,expires_at=NULL WHERE space_id=? AND user_id=?",space,target);
  jdbc.update("UPDATE sys_space_member SET role_type='2' WHERE space_id=? AND user_id=?",space,access.userId());
  audit(space,"space.transfer",target.toString(),Map.of());
 }
 @Transactional public void dissolve(Long space,String confirm){admin(space);var s=access.row("SELECT owner_id,space_name FROM sys_space WHERE id=? FOR UPDATE",space);if(!Objects.equals(((Number)s.get("owner_id")).longValue(),access.userId())||!Objects.equals(s.get("space_name"),confirm))throw new BusinessException(400,"仅创建者输入完整团队名称可解散");audit(space,"space.dissolve",space.toString(),Map.of());jdbc.update("UPDATE sys_space SET status=0 WHERE id=?",space);}
 @Transactional public void settings(Long space,Map<String,Object> b){admin(space);String title=name(b.get("name"),100),description=Objects.toString(b.get("description"),"");long quota=Long.parseLong(b.get("quota").toString());long used=jdbc.queryForObject("SELECT COALESCE(SUM(file_size),0) FROM file_file WHERE space_id=? AND deleted=0 AND status=1",Long.class,space);if(quota<Math.max(1,used)||quota>1099511627776L||description.length()>500)throw new BusinessException(400,"配额不可小于已用空间且最多1TB，简介最多500字");String logo=Objects.toString(b.get("logo"),"");if(logo.length()>255||!logo.isEmpty()&&!logo.matches("https?://[^\\s]+"))throw new BusinessException(400,"Logo须为HTTP图片地址");jdbc.update("UPDATE sys_space SET space_name=?,space_logo=?,description=?,storage_quota=? WHERE id=?",title,logo,description,quota,space);audit(space,"space.settings",space.toString(),b);}
 public List<Map<String,Object>> folder(Long space,String folder){access.requireSpace(space,false);access.requireFolder(Long.valueOf(folder),space);return jdbc.queryForList("SELECT user_id AS userId,permissions_json AS permissions FROM folder_permission WHERE folder_id=?",folder);}
 @Transactional public void folder(Long space,String folder,List<Map<String,Object>> rows){admin(space);access.requireFolder(Long.valueOf(folder),space);if(rows.size()>200)throw new BusinessException(400,"单个文件夹最多200个授权");var seen=new HashSet<Long>();for(var row:rows){Long user=id(row.get("userId"));if(user==null||!seen.add(user))throw new BusinessException(400,"成员缺失或重复");member(space,user);permissions((Map<String,Object>)row.get("permissions"));}jdbc.update("DELETE FROM folder_permission WHERE folder_id=?",folder);for(var row:rows)jdbc.update("INSERT INTO folder_permission(folder_id,user_id,permissions_json) VALUES(?,?,?)",folder,id(row.get("userId")),JSON.toJSONString(row.get("permissions")));audit(space,"folder.permissions",folder,Map.of("entries",rows));}
 private void audit(Long space,String action,String target,Map<String,Object> detail){jdbc.update("INSERT INTO workspace_audit(space_id,actor_id,action,target,detail_json) VALUES(?,?,?,?,?)",space,access.userId(),action,target,JSON.toJSONString(detail));}
 public Map<String,Object> document(Long space,String id){access.requireSpace(space,false);access.requireDocument(id,false);var doc=access.row("SELECT space_id,creator_id FROM doc_document WHERE doc_id=? AND deleted=0",id);if(!Objects.equals(((Number)doc.get("space_id")).longValue(),space))throw new BusinessException(403,"文档不属于此团队");return Map.of("creatorId",doc.get("creator_id"),"grants",jdbc.queryForList("SELECT user_id AS userId,permission FROM doc_member WHERE doc_id=? ORDER BY id",id));}
 @Transactional public void document(Long space,String id,List<Map<String,Object>> rows){var doc=document(space,id);if(!access.isAdmin(space)&&!Objects.equals(((Number)doc.get("creatorId")).longValue(),access.userId()))throw new BusinessException(403,"仅创建者或管理员管理文档权限");access.requireDocumentOperation(id,"share");if(rows.size()>200)throw new BusinessException(400,"最多200名成员");var seen=new HashSet<Long>();for(var row:rows){Long user=id(row.get("userId"));member(space,user);if(!seen.add(user)||!(row.get("permission") instanceof Number p)||!Set.of(1,2,3,4).contains(p.intValue()))throw new BusinessException(400,"成员重复或权限值无效");}jdbc.update("DELETE FROM doc_member WHERE doc_id=? AND user_id<>?",id,doc.get("creatorId"));for(var row:rows)if(!Objects.equals(id(row.get("userId")),((Number)doc.get("creatorId")).longValue()))jdbc.update("INSERT INTO doc_member(doc_id,user_id,permission) VALUES(?,?,?) ON DUPLICATE KEY UPDATE permission=VALUES(permission)",id,id(row.get("userId")),row.get("permission"));audit(space,"document.permissions",id,Map.of("entries",rows));}
}
